-- auto-apply
-- 2026-10-29 conversation review: all 52 learner-facing conversations were
-- read line by line (no AI calls) and second-checked. 44 conversations
-- get fixes — speech-level slips (a boss saying 뵙겠습니다 to staff, friends
-- switching to 해요체 mid-scene), plot contradictions, over-honorific service
-- speech (신청 가능하세요), vocab back in dictionary form, misnamed grammar
-- points and missions that asked for phrases the scene never uses.
-- Each row is replaced only if it still equals the reviewed version, so
-- re-running (or an edit made since) changes nothing. The data column type
-- (json / jsonb / text) is read at run time.
do $$
declare
  t text;
begin
  select case data_type when 'jsonb' then 'jsonb' when 'json' then 'json' else 'text' end
    into t from information_schema.columns
   where table_schema = 'public' and table_name = 'conversations_data' and column_name = 'data';
  if t is null then return; end if;
  execute format($q$
    update public.conversations_data c set data = (%2$L::jsonb)::text::%1$s
     where c.id = 2 and c.data::text::jsonb = %3$L::jsonb
  $q$, t, '{"avi": "👩", "cat": "everyday", "ctx": "Planning dinner together", "lvl": "b", "msgs": [{"s": "l", "txt": "오늘 저녁에 시간 돼?", "who": "Ji-yeon"}, {"s": "r", "txt": "응! 왜? 무슨 일 있어?", "who": "Soo-jin"}, {"s": "l", "txt": "그냥 같이 밥 먹을 사람 찾는 중 ㅋㅋ", "who": "Ji-yeon"}, {"s": "r", "txt": "ㅋㅋ 좋아! 어디서 먹을까?", "who": "Soo-jin"}, {"s": "l", "txt": "학교 앞 국밥집 어때? 요즘 거기 자주 가거든.", "who": "Ji-yeon"}, {"s": "r", "txt": "오 국밥 좋지. 몇 시에?", "who": "Soo-jin"}, {"s": "l", "txt": "6시 반쯤 괜찮아?", "who": "Ji-yeon"}, {"s": "r", "txt": "응 완전 좋아 👍", "who": "Soo-jin"}], "name": "Ji-yeon & Soo-jin", "vocab": [{"en": "to have time / be free", "ko": "시간(이) 되다", "rom": "sigan dwae?"}, {"en": "what''s up / what''s the matter", "ko": "무슨 일", "rom": "museun il"}, {"en": "to look for (찾는 중 = in the middle of looking for)", "ko": "찾다", "rom": "channeun jung"}, {"en": "In front of school", "ko": "학교 앞", "rom": "hakgyo ap"}, {"en": "Often / Frequently", "ko": "자주", "rom": "jaju"}, {"en": "Totally / Completely (slang)", "ko": "완전", "rom": "wanjeon"}], "grammar": [], "mission": [], "catLabel": "Everyday"}', '{"avi": "👩", "cat": "everyday", "ctx": "Planning dinner together", "lvl": "b", "msgs": [{"s": "l", "txt": "오늘 저녁에 시간 돼?", "who": "Ji-yeon"}, {"s": "r", "txt": "응! 왜? 무슨 일 있어?", "who": "Soo-jin"}, {"s": "l", "txt": "그냥 같이 밥 먹을 사람 찾는 중 ㅋㅋ", "who": "Ji-yeon"}, {"s": "r", "txt": "ㅋㅋ 좋아! 어디서 먹을까?", "who": "Soo-jin"}, {"s": "l", "txt": "학교 앞 국밥집 어때? 요즘 거기 자주 가거든.", "who": "Ji-yeon"}, {"s": "r", "txt": "오 국밥 좋지. 몇 시에?", "who": "Soo-jin"}, {"s": "l", "txt": "6시 반쯤 괜찮아?", "who": "Ji-yeon"}, {"s": "r", "txt": "응 완전 좋아 👍", "who": "Soo-jin"}], "name": "Ji-yeon & Soo-jin", "vocab": [{"en": "Do you have time? / Are you free?", "ko": "시간 돼?", "rom": "sigan dwae?"}, {"en": "What\\''s up / What\\''s the matter", "ko": "무슨 일", "rom": "museun il"}, {"en": "In the middle of looking for", "ko": "찾는 중", "rom": "channeun jung"}, {"en": "In front of school", "ko": "학교 앞", "rom": "hakgyo ap"}, {"en": "Often / Frequently", "ko"