  $q$, t, '{"avi": "🍻", "cat": "work", "ctx": "Team dinner after work — navigating workplace social dynamics", "lvl": "i", "msgs": [{"s": "l", "txt": "오늘 다들 수고했어요. 자, 건배!", "who": "팀장"}, {"s": "r", "txt": "건배! 팀장님, 오늘 발표 정말 잘하셨어요.", "who": "민서", "en": ""}, {"s": "l", "txt": "에이, 민서 씨가 자료 준비를 잘 해줬잖아요.", "who": "팀장"}, {"s": "r", "txt": "같이 잘한 거죠, 뭐. 다음 프로젝트도 기대됩니다.", "who": "민서", "en": ""}, {"s": "l", "txt": "그렇죠. 다음 건도 민서 씨한테 맡기고 싶어요.", "who": "팀장"}, {"s": "r", "txt": "감사합니다. 열심히 하겠습니다. 근데 팀장님, 주량이 어떻게 되세요?", "who": "민서"}, {"s": "l", "txt": "하하, 저는 소주 한 병 반 정도요. 민서 씨는요?", "who": "팀장"}, {"s": "r", "txt": "저는 좀 못 마시는 편이에요. 한 잔 정도?", "who": "민서"}, {"s": "l", "txt": "그럼 맥주로 바꿀까요? 편하게 마셔요.", "who": "팀장"}, {"s": "r", "txt": "감사합니다. 팀장님이랑 일하면서 많이 배우고 있어요.", "who": "민서"}, {"s": "l", "txt": "저도 민서 씨 덕분에 편하게 일하고 있어요.", "who": "팀장"}, {"s": "r", "txt": "이런 말씀 해주시니까 너무 감사해요. 오늘 즐겁게 마시겠습니다!", "who": "민서"}], "name": "회식 자리", "topic": "Workplace Social", "vocab": [{"en": "Cheers! (toast)", "ko": "건배", "rom": "geonbae"}, {"en": "alcohol tolerance / drinking capacity", "ko": "주량", "rom": "juryang"}, {"en": "soju (Korean distilled spirit)", "ko": "소주", "rom": "soju"}, {"en": "to entrust / leave (a task) to someone", "ko": "맡기다", "rom": "-hante matgida"}, {"en": "tend to ~ / be the type who ~", "ko": "~는 편이다", "rom": "-neun pyeonida"}, {"en": "thanks to (positive; N 덕분에)", "ko": "덕분", "rom": "-deokbune"}], "grammar": [{"point": "~고 싶어요", "example": "맡기고 싶어요", "meaning": "I want to ~"}, {"point": "~면서", "example": "일하면서", "meaning": "while ~ing / as ~"}], "mission": [{"task": "Give a compliment to a colleague using ~덕분에 and respond humbly"}]}', '{"avi": "🍻", "cat": "work", "ctx": "Team dinner after work — navigating workplace social dynamics", "lvl": "i", "msgs": [{"s": "l", "txt": "오늘 다들 수고했어요. 자, 건배!", "who": "팀장"}, {"s": "r", "txt": "건배! 팀장님, 오늘 발표 정말 잘 하셨어요.", "who": "민서"}, {"s": "l", "txt": "에이, 민서 씨가 자료 준비를 잘 해줬잖아요.", "who": "팀장"}, {"s": "r", "txt": "같이 잘 한 거죠, 뭐. 다음 프로젝트도 기대됩니다.", "who": "민서"}, {"s": "l", "txt": "그렇죠. 다음 건도 민서 씨한테 맡기고 싶어요.", "who": "팀장"}, {"s": "r", "txt": "감사합니다. 열심히 하겠습니다. 근데 팀장님, 주량이 어떻게 되세요?", "who": "민서"}, {"s": "l", "txt": "하하, 저는 소주 한 병 반 정도요. 민서 씨는요?", "who": "팀장"}, {"s": "r", "txt": "저는 좀 못 마시는 편이에요. 한 잔 정도?", "who": "민서"}, {"s": "l", "txt": "그럼 맥주로 바꿀까요? 편하게 마셔요.", "who": "팀장"}, {"s": "r", "txt": "감사합니다. 팀장님이랑 일하면서 많이 배우고 있어요.", "who": "민서"}, {"s": "l", "txt": "저도 민서 씨 덕분에 편하게 일하고 있어요.", "who": "팀장"}, {"s": "r", "txt": "이런 말씀 해주시니까 너무 감사해요. 오늘 즐겁게 마시겠습니다!", "who": "민서"}], "name": "회식 자리", "topic": "Workplace Social", "vocab": [{"en": "Cheers! (toast)", "ko": "건배", "rom": "geonbae"}, {"en": "alcohol tolerance / drinking capacity", "ko": "주량", "rom": "juryang"}, {"en": "soju (Korean distilled spirit)", "ko": "소주", "rom": "soju"}, {"en": "to entrust ~ to someone", "ko": "~한테 맡기다", "rom": "-hante matgida"}, {"en": "tend to ~ / be the type who ~", "ko": "~는 편이다", "rom": "-neun pyeonida"}, {"en": "thanks to ~ / because of ~ (positive)", "ko": "~덕분에", "rom": "-deokbune"}], "grammar": [{"point": "~고 싶어요", "example": "맡기고 싶어요", "meaning": "I want to ~"}, {"point": "~면서", "example": "일하면서", "meaning": "while ~ing / as ~"}], "mission": [{"task": "Give a compliment to a colleague using ~덕분에 and respond humbly"}]}');
