  $q$, t, '{"avi": "🏥", "cat": "everyday", "ctx": "Calling to book an appointment and consulting with a doctor", "lvl": "a", "msgs": [{"s": "l", "txt": "안녕하세요, 서울내과의원입니다.", "who": "간호사"}, {"s": "r", "txt": "안녕하세요. 진료 예약을 하고 싶어서요. 내과 맞죠?", "who": "환자"}, {"s": "l", "txt": "네, 맞습니다. 어떤 증상으로 오시려고요?", "who": "간호사"}, {"s": "r", "txt": "며칠째 소화가 잘 안 되고, 속이 더부룩하고 가끔 메스꺼워요.", "who": "환자"}, {"s": "l", "txt": "언제부터 그러셨어요?", "who": "간호사"}, {"s": "r", "txt": "한 5일 정도 됐어요. 처음엔 그냥 넘겼는데 좀 지속되네요.", "who": "환자"}, {"s": "l", "txt": "가장 빠른 게 내일 오전 10시인데 괜찮으세요?", "who": "간호사"}, {"s": "r", "txt": "네, 좋습니다. 준비할 게 있나요? 금식 같은 거요.", "who": "환자"}, {"s": "l", "txt": "상황에 따라 내시경 검사가 필요할 수 있어서, 전날 밤부터 금식하고 오시는 게 좋겠어요.", "who": "간호사", "en": ""}, {"s": "r", "txt": "알겠습니다. 건강보험은 적용되나요?", "who": "환자"}, {"s": "l", "txt": "기본 진료는 적용되고요, 검사 종류에 따라 본인부담금이 달라질 수 있어요.", "who": "간호사"}, {"s": "r", "txt": "이해했습니다. 내일 10시에 찾아뵙겠습니다. 감사합니다.", "who": "환자"}], "name": "병원 예약과 상담", "topic": "Health", "vocab": [{"en": "medical examination / consultation", "ko": "진료", "rom": "jillyo"}, {"en": "to feel bloated / full and uncomfortable", "ko": "더부룩하다", "rom": "deobureukada"}, {"en": "to feel nauseous", "ko": "메스껍다", "rom": "meseukkeopda"}, {"en": "endoscopy", "ko": "내시경", "rom": "naesigyeong"}, {"en": "fasting", "ko": "금식", "rom": "geumsik"}, {"en": "patient co-payment / out-of-pocket cost", "ko": "본인부담금", "rom": "bonin-budamgeum"}], "grammar": [{"point": "~(으)ㄹ 수 있어서", "example": "검사가 필요할 수 있어서", "meaning": "because ~ might be needed (cautious)"}, {"point": "~에 따라", "example": "검사 종류에 따라", "meaning": "depending on ~"}], "mission": [{"task": "Describe physical symptoms accurately using 더부룩하다, 메스껍다 in context"}]}', '{"avi": "🏥", "cat": "everyday", "ctx": "Calling to book an appointment and consulting with a doctor", "lvl": "a", "msgs": [{"s": "l", "txt": "안녕하세요, 서울내과의원입니다.", "who": "간호사"}, {"s": "r", "txt": "안녕하세요. 진료 예약을 하고 싶어서요. 내과 맞죠?", "who": "환자"}, {"s": "l", "txt": "네, 맞습니다. 어떤 증상으로 오시려고요?", "who": "간호사"}, {"s": "r", "txt": "며칠째 소화가 잘 안 되고, 속이 더부룩하고 가끔 메스꺼워요.", "who": "환자"}, {"s": "l", "txt": "언제부터 그러셨어요?", "who": "간호사"}, {"s": "r", "txt": "한 5일 정도 됐어요. 처음엔 그냥 넘겼는데 좀 지속되네요.", "who": "환자"}, {"s": "l", "txt": "가장 빠른 게 내일 오전 10시인데 괜찮으세요?", "who": "간호사"}, {"s": "r", "txt": "네, 좋습니다. 준비할 게 있나요? 금식 같은 거요.", "who": "환자"}, {"s": "l", "txt": "상황에 따라 내시경 검사가 필요할 수 있어서, 4시간 전부터 금식하고 오시는 게 좋을 것 같아요.", "who": "간호사"}, {"s": "r", "txt": "알겠습니다. 건강보험은 적용되나요?", "who": "환자"}, {"s": "l", "txt": "기본 진료는 적용되고요, 검사 종류에 따라 본인부담금이 달라질 수 있어요.", "who": "간호사"}, {"s": "r", "txt": "이해했습니다. 내일 10시에 찾아뵙겠습니다. 감사합니다.", "who": "환자"}], "name": "병원 예약과 상담", "topic": "Health", "vocab": [{"en": "medical examination / consultation", "ko": "진료", "rom": "jillyo"}, {"en": "to feel bloated / full and uncomfortable", "ko": "더부룩하다", "rom": "deobureukada"}, {"en": "to feel nauseous", "ko": "메스껍다", "rom": "meseukkeopda"}, {"en": "endoscopy", "ko": "내시경", "rom": "naesigyeong"}, {"en": "fasting", "ko": "금식", "rom": "geumsik"}, {"en": "patient co-payment / out-of-pocket cost", "ko": "본인부담금", "rom": "bonin-budamgeum"}], "grammar": [{"point": "~(으)ㄹ 수 있어서", "example": "검사가 필요할 수 있어서", "meaning": "because ~ might be needed (cautious)"}, {"point": "~에 따라", "example": "검사 종류에 따라", "meaning": "depending on ~"}], "mission": [{"task": "Describe physical symptoms accurately using 더부룩하다, 메스껍다 in context"}]}');
