  $q$, t, '{"avi": "💬", "cat": "friends", "ctx": "초등학교 친구를 10년 만에 우연히 만남", "lvl": "s", "msgs": [{"s": "l", "en": "Huh? Is that Sujin?", "txt": "어? 수진이야?", "who": "지민"}, {"s": "r", "en": "It''s Jimin!", "txt": "지민이다!", "who": "수진"}, {"s": "l", "en": "It''s been so long.", "txt": "진짜 오랜만이야.", "who": "지민"}, {"s": "r", "en": "Right! How many years has it been?", "txt": "맞아! 몇 년 만이지?", "who": "수진"}, {"s": "l", "en": "It''s been ten years.", "txt": "십 년 만이야.", "who": "지민"}, {"s": "r", "en": "Wow, that''s crazy!", "txt": "와, 대박!", "who": "수진"}, {"s": "l", "en": "What do you do now?", "txt": "지금 뭐 해?", "who": "지민"}, {"s": "r", "en": "I''m an office worker. How about you?", "txt": "회사원이야. 너는?", "who": "수진"}], "name": "지민, 수진", "topic": "어릴 때 친구를 길에서 우연히 만남", "vocab": [{"en": "a long time (since you last met)", "ko": "오랜만", "rom": "oraedwaesseoyo"}, {"en": "how many years", "ko": "몇 년", "rom": "myeot nyeon"}, {"en": "ten years", "ko": "십 년", "rom": "sip nyeon"}, {"en": "amazing/awesome", "ko": "대박", "rom": "daebak"}, {"en": "office worker", "ko": "회사원", "rom": "hoesawon"}], "grammar": [{"ex": "십 년 만이야. (It''s been ten years.)", "point": "N 만이다 – it''s been N (since last time)"}, {"ex": "회사원이야. (I''m an office worker.)", "point": "N(이)다 / N(이)야 – casual ''to be''"}], "mission": ["Practice recognizing old friends with ''어? ~이야?'' pattern", "Say how long it''s been using ''~ 만이야'' (e.g. 십 년 만이야)", "Ask about current jobs using ''지금 뭐 해?''"], "catLabel": "Friends"}', '{"avi": "💬", "cat": "friends", "ctx": "초등학교 친구를 10년 만에 우연히 만남", "lvl": "s", "msgs": [{"s": "l", "en": "Huh? Is that Sujin?", "txt": "어? 수진이야?", "who": "지민"}, {"s": "r", "en": "It''s Jimin!", "txt": "지민이다!", "who": "수진"}, {"s": "l", "en": "It''s been so long.", "txt": "정말 오래됐어요.", "who": "지민"}, {"s": "r", "en": "Right! How many years?", "txt": "맞아요! 몇 년이에요?", "who": "수진"}, {"s": "l", "en": "Ten years.", "txt": "십 년이에요.", "who": "지민"}, {"s": "r", "en": "Wow, that''s amazing!", "txt": "와, 대박이에요!", "who": "수진"}, {"s": "l", "en": "What do you do now?", "txt": "지금 뭐 해요?", "who": "지민"}, {"s": "r", "en": "I''m an office worker. How about you, Jimin?", "txt": "회사원이에요. 지민이는요?", "who": "수진"}], "name": "지민, 수진", "topic": "어릴 때 친구를 길에서 우연히 만남", "vocab": [{"en": "it''s been a long time", "ko": "오래됐어요", "rom": "oraedwaesseoyo"}, {"en": "how many years", "ko": "몇 년", "rom": "myeot nyeon"}, {"en": "ten years", "ko": "십 년", "rom": "sip nyeon"}, {"en": "amazing/awesome", "ko": "대박", "rom": "daebak"}, {"en": "office worker", "ko": "회사원", "rom": "hoesawon"}], "grammar": [{"ex": "회사원이에요 (I''m an office worker)", "point": "~이에요/예요 (polite form of ''to be'')"}, {"ex": "지민이다! (It''s Jimin!)", "point": "~이다 (casual form of ''to be'')"}], "mission": ["Practice recognizing old friends with ''어? ~이야?'' pattern", "Use time expressions like ''십 년이에요'' to talk about duration", "Ask about current jobs using ''지금 뭐 해요?''"], "catLabel": "Friends"}');
