  $q$, t, '{"avi": "💬", "cat": "family", "ctx": "동생 민지가 형 지훈의 새 후드티를 몰래 입고 나갔다", "lvl": "b", "msgs": [{"s": "l", "en": "Hey! Where did my new hoodie go?", "txt": "야! 내 새 후드티 어디 갔어?", "who": "지훈"}, {"s": "r", "en": "I don''t know~ Why?", "txt": "몰라~ 왜?", "who": "민지"}, {"s": "l", "en": "I definitely hung it in the closet but it''s gone", "txt": "분명히 옷장에 걸어뒀는데 없어", "who": "지훈"}, {"s": "r", "en": "Oh... I wore that out hehe", "txt": "아... 그거 내가 입고 나왔어 ㅎㅎ", "who": "민지"}, {"s": "l", "en": "What?! Why did you secretly take my clothes?", "txt": "뭐?! 왜 내 옷을 몰래 가져가?", "who": "지훈"}, {"s": "r", "en": "Sorry ㅠㅠ I had no clothes to wear today", "txt": "미안해ㅠㅠ 오늘 입을 옷이 없었어", "who": "민지"}, {"s": "l", "en": "Ask first next time!", "txt": "다음부터는 먼저 물어봐!", "who": "지훈"}, {"s": "r", "en": "Got it! I''ll buy you chicken~", "txt": "알겠어! 치킨 사줄게~", "who": "민지"}], "name": "지훈 & 민지", "topic": "동생이 내 옷 몰래 입고 나감", "vocab": [{"en": "hoodie", "ko": "후드티", "rom": "hudeu-ti"}, {"en": "closet", "ko": "옷장", "rom": "otjang"}, {"en": "to hang", "ko": "걸다", "rom": "geolda"}, {"en": "secretly", "ko": "몰래", "rom": "mollae"}, {"en": "to take away", "ko": "가져가다", "rom": "gajyeogada"}, {"en": "to ask", "ko": "물어보다", "rom": "mureoboda"}, {"en": "chicken", "ko": "치킨", "rom": "chikin"}], "grammar": [{"ex": "내 가방 어디 갔어? (Where did my bag go?)", "point": "어디 갔어? - Where did it go?"}, {"ex": "분명히 옷장에 걸어 뒀는데 없어. (I definitely hung it in the closet, but it''s not there.)", "point": "-(으)ㄴ/는데 – but (contrast, connecting clauses)"}, {"ex": "다음부터는 일찍 와 (Come early from next time)", "point": "다음부터는 - from next time"}], "mission": ["Ask where something went using ''어디 갔어?''", "Apologize for taking something without permission", "Promise to ask first next time using ''다음부터는''"], "catLabel": "Family"}', '{"avi": "💬", "cat": "family", "ctx": "동생 민지가 형 지훈의 새 후드티를 몰래 입고 나갔다", "lvl": "b", "msgs": [{"s": "l", "en": "Hey! Where did my new hoodie go?", "txt": "야! 내 새 후드티 어디 갔어?", "who": "지훈"}, {"s": "r", "en": "I don''t know~ Why?", "txt": "몰라~ 왜?", "who": "민지"}, {"s": "l", "en": "I definitely hung it in the closet but it''s gone", "txt": "분명히 옷장에 걸어뒀는데 없어", "who": "지훈"}, {"s": "r", "en": "Oh... I wore that out hehe", "txt": "아... 그거 내가 입고 나왔어 ㅎㅎ", "who": "민지"}, {"s": "l", "en": "What?! Why did you secretly take my clothes?", "txt": "뭐?! 왜 내 옷을 몰래 가져가?", "who": "지훈"}, {"s": "r", "en": "Sorry ㅠㅠ I had no clothes to wear today", "txt": "미안해ㅠㅠ 오늘 입을 옷이 없었어", "who": "민지"}, {"s": "l", "en": "Ask first next time!", "txt": "다음부터는 먼저 물어봐!", "who": "지훈"}, {"s": "r", "en": "Got it! I''ll buy you chicken~", "txt": "알겠어! 치킨 사줄게~", "who": "민지"}], "name": "지훈 & 민지", "topic": "동생이 내 옷 몰래 입고 나감", "vocab": [{"en": "hoodie", "ko": "후드티", "rom": "hudeu-ti"}, {"en": "closet", "ko": "옷장", "rom": "otjang"}, {"en": "to hang", "ko": "걸다", "rom": "geolda"}, {"en": "secretly", "ko": "몰래", "rom": "mollae"}, {"en": "to take away", "ko": "가져가다", "rom": "gajyeogada"}, {"en": "to ask", "ko": "물어보다", "rom": "mureoboda"}, {"en": "chicken", "ko": "치킨", "rom": "chikin"}], "grammar": [{"ex": "내 가방 어디 갔어? (Where did my bag go?)", "point": "어디 갔어? - Where did it go?"}, {"ex": "비가 오는데 우산이 없어 (It''s raining but I don''t have an umbrella)", "point": "~는데 - but/however (connecting clauses)"}, {"ex": "다음부터는 일찍 와 (Come early from next time)", "point": "다음부터는 - from next time"}], "mission": ["Ask where something went using ''어디 갔어?''", "Apologize for taking something without permission", "Promise to ask first next time using ''다음부터는''"], "catLabel": "Family"}');
