  $q$, t, '{"avi": "💬", "cat": "work", "ctx": "월요일 아침 회의에서 졸린 민수와 옆자리 지현이 속닥거림", "lvl": "b", "msgs": [{"s": "l", "en": "Ugh... I can''t keep my eyes open...", "txt": "어... 눈이 안 떠져...", "who": "민수"}, {"s": "r", "en": "Hey, the manager is watching!", "txt": "야, 부장님이 보고 있어!", "who": "지현"}, {"s": "l", "en": "I slept too late over the weekend ㅠㅠ", "txt": "주말에 너무 늦게 잤어 ㅠㅠ", "who": "민수"}, {"s": "r", "en": "You need coffee. Should I go out and get some now?", "txt": "커피 마셔야 해. 지금 나가서 사 올까?", "who": "지현"}, {"s": "l", "en": "No, don''t. We''re in a meeting. I''m okay...", "txt": "안 돼. 회의 중이야. 괜찮아...", "who": "민수"}, {"s": "r", "en": "Pinch your arm. It''ll wake you up.", "txt": "팔 꼬집어 봐. 잠 깰 거야.", "who": "지현"}, {"s": "l", "en": "Ouch! It works ㅋㅋ Thanks", "txt": "아야! 효과 있네 ㅋㅋ 고마워", "who": "민수"}, {"s": "r", "en": "Sleep early next time. Got it?", "txt": "다음엔 일찍 자. 알았지?", "who": "지현"}], "name": "민수 & 지현", "topic": "월요일 9시 회의에서 졸음, 옆 동료와 속닥", "vocab": [{"en": "can''t keep eyes open", "ko": "눈이 안 떠지다", "rom": "nuni an tteojida"}, {"en": "manager, department head", "ko": "부장님", "rom": "bujangnim"}, {"en": "to sleep late", "ko": "늦게 자다", "rom": "neutge jada"}, {"en": "during a meeting", "ko": "회의 중", "rom": "hoeui jung"}, {"en": "to pinch", "ko": "꼬집다", "rom": "kkojipda"}], "grammar": [{"ex": "눈이 안 떠져. (My eyes won''t open.)", "point": "안 + verb – negation (won''t / not)"}, {"ex": "부장님이 보고 있어 (manager is watching)", "point": "-고 있다 (present continuous)"}, {"ex": "커피 마셔야 해 (should drink coffee)", "point": "-아/어야 하다 (must/should)"}], "mission": ["Say you can''t keep your eyes open using ''눈이 안 떠져''", "Offer to get something for someone using ''사 올까?''", "Give advice using ''-아/어야 해'' (e.g. 커피 마셔야 해)"], "catLabel": "Workplace"}', '{"avi": "💬", "cat": "work", "ctx": "월요일 아침 회의에서 졸린 민수와 옆자리 지현이 속닥거림", "lvl": "b", "msgs": [{"s": "l", "en": "Ugh... I can''t keep my eyes open...", "txt": "어... 눈이 안 떠져...", "who": "민수"}, {"s": "r", "en": "Hey, the manager is watching!", "txt": "야, 부장님이 보고 있어!", "who": "지현"}, {"s": "l", "en": "I slept too late over the weekend ㅠㅠ", "txt": "주말에 너무 늦게 잤어 ㅠㅠ", "who": "민수"}, {"s": "r", "en": "You need to drink coffee. Should I go buy some now?", "txt": "커피 마셔야 해. 지금 나가서 사올까?", "who": "지현"}, {"s": "l", "en": "No, don''t. We''re in a meeting. I''m okay...", "txt": "안 돼. 회의 중이야. 괜찮아...", "who": "민수"}, {"s": "r", "en": "Pinch your arm. It''ll wake you up.", "txt": "팔 꼬집어. 잠 깨워.", "who": "지현"}, {"s": "l", "en": "Ouch! It works ㅋㅋ Thanks", "txt": "아야! 효과 있네 ㅋㅋ 고마워", "who": "민수"}, {"s": "r", "en": "Sleep early next time. Got it?", "txt": "다음엔 일찍 자. 알았지?", "who": "지현"}], "name": "민수 & 지현", "topic": "월요일 9시 회의에서 졸음, 옆 동료와 속닥", "vocab": [{"en": "can''t keep eyes open", "ko": "눈이 안 떠지다", "rom": "nuni an tteojida"}, {"en": "manager, department head", "ko": "부장님", "rom": "bujangnim"}, {"en": "to sleep late", "ko": "늦게 자다", "rom": "neutge jada"}, {"en": "during a meeting", "ko": "회의 중", "rom": "hoeui jung"}, {"en": "to pinch", "ko": "꼬집다", "rom": "kkojipda"}], "grammar": [{"ex": "눈이 안 떠져 (can''t open eyes), 안 돼 (can''t/shouldn''t)", "point": "안 + 동사 (negation)"}, {"ex": "부장님이 보고 있어 (manager is watching)", "point": "-고 있다 (present continuous)"}, {"ex": "커피 마셔야 해 (should drink coffee)", "point": "-아/어야 하다 (must/should)"}], "mission": ["Say you''re sleepy using ''졸리다''", "Ask if someone wants coffee using ''커피 마실래?''", "Suggest doing something together using ''-을까?''"], "catLabel": "Workplace"}');
  execute format($q$
