  $q$, t, '{"avi": "💬", "cat": "everyday", "ctx": "미용실에서 머리를 자르고 거울을 본 지수의 충격적인 반응", "lvl": "i", "msgs": [{"s": "l", "en": "Minji... I''m at the salon right now and it''s totally ruined ㅠㅠ", "txt": "민지야... 나 지금 미용실인데 완전 망했어 ㅠㅠ", "who": "지수"}, {"s": "r", "en": "Huh? What do you mean ruined? You were getting your hair cut", "txt": "어? 뭐가 망했다는 거야? 머리 자르고 있었잖아", "who": "민지"}, {"s": "l", "en": "As soon as I looked in the mirror, I really wanted to cry... What is this, seriously", "txt": "거울 보자마자 진짜 울고 싶었어... 이게 뭐야 진짜", "who": "지수"}, {"s": "r", "en": "Is it that weird? Send me a picture!", "txt": "그렇게 이상해? 사진 좀 보내봐!", "who": "민지"}, {"s": "l", "en": "What picture... I can''t show this to people in this state", "txt": "사진은 무슨... 사람들한테 보여줄 수가 없어 이 상태로는", "who": "지수"}, {"s": "r", "en": "Oh, then come out wearing a hat. I''ll buy one nearby and bring it to you", "txt": "아 그럼 모자 쓰고 나와. 내가 근처에서 모자 하나 사서 갖다줄게", "who": "민지"}, {"s": "l", "en": "Thanks... I should never go to a new salon again", "txt": "고마워... 다음에는 절대 새로운 미용실 가지 말아야겠어", "who": "지수"}, {"s": "r", "en": "Right, you really need to be careful with hair. I''ll be right there!", "txt": "맞아, 머리는 진짜 신중하게 해야 하는데. 금방 갈게!", "who": "민지"}], "name": "지수와 민지", "topic": "미용실에서 머리 망함, 거울 보고 첫 반응", "vocab": [{"en": "to be ruined, to fail", "ko": "망하다", "rom": "manghada"}, {"en": "mirror", "ko": "거울", "rom": "geoul"}, {"en": "state, condition", "ko": "상태", "rom": "sangtae"}, {"en": "to bring (something) to someone", "ko": "갖다주다", "rom": "yakguk"}, {"en": "to be careful / cautious (신중하게 = carefully)", "ko": "신중하다", "rom": "sinjunghage"}], "grammar": [{"ex": "거울 보자마자 울고 싶었어 (As soon as I looked in the mirror, I wanted to cry)", "point": "-자마자 (as soon as)"}, {"ex": "다음에는 절대 새로운 미용실 가지 말아야겠어. (Next time I definitely shouldn''t go to a new salon.)", "point": "-아/어야겠다 – (I''ve decided) I should / I''d better"}], "mission": ["What does 지수 see when she looks in the mirror?", "What solution does 민지 suggest?", "What does 지수 decide about trying new salons?"], "catLabel": "Everyday"}', '{"avi": "💬", "cat": "everyday", "ctx": "미용실에서 머리를 자르고 거울을 본 지수의 충격적인 반응", "lvl": "i", "msgs": [{"s": "l", "en": "Minji... I''m at the salon right now and it''s totally ruined ㅠㅠ", "txt": "민지야... 나 지금 미용실인데 완전 망했어 ㅠㅠ", "who": "지수"}, {"s": "r", "en": "Huh? What do you mean ruined? You were getting your hair cut", "txt": "어? 뭐가 망했다는 거야? 머리 자르고 있었잖아", "who": "민지"}, {"s": "l", "en": "As soon as I looked in the mirror, I really wanted to cry... What is this, seriously", "txt": "거울 보자마자 진짜 울고 싶었어... 이게 뭐야 진짜", "who": "지수"}, {"s": "r", "en": "Is it that weird? Send me a picture!", "txt": "그렇게 이상해? 사진 좀 보내봐!", "who": "민지"}, {"s": "l", "en": "What picture... I can''t show this to people in this state", "txt": "사진은 무슨... 사람들한테 보여줄 수가 없어 이 상태로는", "who": "지수"}, {"s": "r", "en": "Oh then come out wearing a hat. I''ll buy a hat from the pharmacy and bring it to you", "txt": "아 그럼 모자 쓰고 나와. 내가 약국에서 모자 사서 갖다줄게", "who": "민지"}, {"s": "l", "en": "Thanks... I should never go to a new salon again", "txt": "고마워... 다음에는 절대 새로운 미용실 가지 말아야겠어", "who": "지수"}, {"s": "r", "en": "Right, you really need to be careful with hair. I''ll be right there!", "txt": "맞아, 머리는 진짜 신중하게 해야 하는데. 금방 갈게!", "who": "민지"}], "name": "지수와 민지", "topic": "미용실에서 머리 망함, 거울 보고 첫 반응", "vocab": [{"en": "to be ruined, to fail", "ko": "망하다", "rom": "manghada"}, {"en": "mirror", "ko": "거울", "rom": "geoul"}, {"en": "state, condition", "ko": "상태", "rom": "sangtae"}, {"en": "pharmacy", "ko": "약국", "rom": "yakguk"}, {"en": "carefully, cautiously", "ko": "신중하게", "rom": "sinjunghage"}], "grammar": [{"ex": "거울 보자마자 울고 싶었어 (As soon as I looked in the mirror, I wanted to cry)", "point": "-자마자 (as soon as)"}, {"ex": "가지 말아야겠어 (I shouldn''t go)", "point": "-아/어야겠어 (should/must)"}], "mission": ["What does 지수 see when she looks in the mirror?", "What solution does 민지 suggest?", "What does 지수 decide about trying new salons?"], "catLabel": "Everyday"}');
  execute format($q$
