  $q$, t, '{"avi": "☕", "cat": "food", "ctx": "친구들이 카페에서 만나서 주문하는 상황", "lvl": "b", "msgs": [{"s": "l", "en": "Hi! Let''s sit here.", "txt": "안녕! 여기 앉자.", "who": "지민"}, {"s": "r", "en": "Good. What should we drink?", "txt": "좋아. 뭐 마실까?", "who": "수진"}, {"s": "l", "en": "I want to drink an Americano.", "txt": "나는 아메리카노 마실래.", "who": "지민"}, {"s": "r", "en": "I think a latte would be good for me.", "txt": "나는 라떼가 좋겠어.", "who": "수진"}, {"s": "l", "en": "Should we eat cake too?", "txt": "케이크도 먹을까?", "who": "지민"}, {"s": "r", "en": "Yes! How about strawberry cake?", "txt": "응! 딸기 케이크 어때?", "who": "수진"}, {"s": "l", "en": "Good. I''ll order.", "txt": "좋아. 내가 주문할게.", "who": "지민"}, {"s": "r", "en": "Thank you!", "txt": "고마워!", "who": "수진"}], "name": "지민, 수진", "topic": "카페에서 주문하기", "vocab": [{"en": "to sit", "ko": "앉다", "rom": "anta"}, {"en": "to drink", "ko": "마시다", "rom": "masida"}, {"en": "Americano", "ko": "아메리카노", "rom": "amerikano"}, {"en": "latte", "ko": "라떼", "rom": "latte"}, {"en": "cake", "ko": "케이크", "rom": "keikeu"}, {"en": "strawberry", "ko": "딸기", "rom": "ttalgi"}, {"en": "to order", "ko": "주문하다", "rom": "jumunhada"}], "grammar": [{"ex": "마실래 (I want to drink)", "point": "-(으)ㄹ래요/-(으)ㄹ래: expressing intention or desire"}, {"ex": "좋겠어 (would be good)", "point": "-겠어요/-겠어: expressing opinion or supposition"}], "mission": ["카페에서 음료 주문해보기", "친구와 함께 먹을 디저트 정하기", "''-ㄹ래'' 를 사용해서 의사 표현하기"], "catLabel": "undefined", "key_expressions": [{"en": "what should we drink", "ko": "뭐 마실까"}, {"en": "I''ll order", "ko": "내가 주문할게"}, {"en": "thank you", "ko": "고마워"}]}', '{"avi": "☕", "cat": "food", "ctx": "친구들이 카페에서 만나서 주문하는 상황", "lvl": "b", "msgs": [{"s": "l", "en": "Hi! Let''s sit here.", "txt": "안녕! 여기 앉자.", "who": "지민"}, {"s": "r", "en": "Good. What should we drink?", "txt": "좋아. 뭐 마실까?", "who": "수진"}, {"s": "l", "en": "I want to drink an Americano.", "txt": "나는 아메리카노 마실래.", "who": "지민"}, {"s": "r", "en": "I think a latte would be good for me.", "txt": "나는 라떼가 좋겠어.", "who": "수진"}, {"s